import socket, sys, chess, concurrent.futures as cf
sys.path.insert(0,"/workdir"); import arena
def analyse(board, mt):
    s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.connect("/run/match/engine.sock"); f=s.makefile("r")
    def send(c): s.sendall((c+"\n").encode())
    def wait(t):
        L=[]
        while True:
            l=f.readline().strip(); L.append(l)
            if l.startswith(t): return L
    send("uci"); wait("uciok"); send("setoption name Threads value 2"); send("setoption name Hash value 256"); send("isready"); wait("readyok")
    send("position startpos moves "+" ".join(m.uci() for m in board.move_stack)); send(f"go movetime {mt}")
    L=wait("bestmove"); send("quit")
    info=[l for l in L if l.startswith("info") and " pv " in l and "bound" not in l]
    w=info[-1].split(); sc=w[w.index("score")+1:w.index("score")+3]; d=w[w.index("depth")+1]
    val = int(sc[1]) if sc[0]=="cp" else (100000-int(sc[1])*10 if int(sc[1])>0 else -100000-int(sc[1])*10)
    return val, sc, d, " ".join(w[w.index("pv")+1:w.index("pv")+10])
def rootsplit(board, moves, mt, workers=14):
    res={}
    def job(m):
        b=board.copy(); b.push(m)
        if b.is_checkmate(): return m, (10**6, ["mate","0"], "0", "")
        v,sc,d,pv=analyse(b, mt); return m,(-v,sc,d,pv)
    with cf.ThreadPoolExecutor(workers) as ex:
        for m,r in ex.map(job, moves): res[m]=r
    return res
if __name__=="__main__":
    board=arena.load_board(); mt=int(sys.argv[1])
    moves=list(board.legal_moves) if len(sys.argv)<3 else [chess.Move.from_uci(u) for u in sys.argv[2:]]
    res=rootsplit(board, moves, mt)
    print(board.fen())
    for m,(v,sc,d,pv) in sorted(res.items(), key=lambda x:-x[1][0]):
        print(f"{board.san(m):8s} {v:6d} d{d:3s} {pv}")
